"""Bounded character-prefix-aware DataFrame column reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Optimize row serialization with global and recursive conditional orders."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the latest returned row orderings."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Convert one scalar to evaluator text, mapping scalar missing values to empty text."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length with binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Score serialized rows by LCPs of lexicographically adjacent strings."""
        if len(strings) < 2:
            return 0
        values = sorted(strings)
        return sum(cls._lcp(a, b) for a, b in zip(values, values[1:]))

    @staticmethod
    def _dependency_edges(columns, requested):
        """Translate named pairs or chains into unique directed column-index edges."""
        positions = {}
        for i, name in enumerate(columns):
            positions.setdefault(str(name), []).append(i)

        edges, seen = [], set()

        def add(a, b):
            """Add one valid named dependency."""
            left = positions.get(str(a), [])
            right = positions.get(str(b), [])
            if len(left) == 1 and len(right) == 1 and left[0] != right[0]:
                edge = (left[0], right[0])
                if edge not in seen:
                    seen.add(edge)
                    edges.append(edge)

        for item in requested or []:
            if isinstance(item, (list, tuple)):
                if len(item) == 2:
                    add(item[0], item[1])
                elif len(item) > 2:
                    for a, b in zip(item, item[1:]):
                        add(a, b)
        return edges

    @classmethod
    def _constrained_order(cls, m, preference, columns, requested):
        """Return a deterministic preference-ranked topological column order."""
        outgoing = [[] for _ in range(m)]
        indegree = [0] * m
        for a, b in cls._dependency_edges(columns, requested):
            outgoing[a].append(b)
            indegree[b] += 1

        rank = {c: i for i, c in enumerate(preference)}
        heap = [(rank[c], c) for c in range(m) if indegree[c] == 0]
        heapq.heapify(heap)
        result = []

        while heap:
            _, col = heapq.heappop(heap)
            result.append(col)
            for nxt in outgoing[col]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank[nxt], nxt))

        return result if len(result) == m else list(preference)

    @staticmethod
    def _statistics(text):
        """Compute whole-column length-weighted repetition statistics once."""
        n, m = text.shape
        result = []
        for col in range(m):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1
            pair = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            repeat = sum(
                len(value) * max(0, count - 1)
                for value, count in counts.items()
            )
            total = sum(len(value) * count for value, count in counts.items())
            result.append((pair, repeat, total))
        return result

    @staticmethod
    def _serialize(text, orders):
        """Serialize each source row according to its row-specific column order."""
        return [
            "".join(text[row, col] for col in orders[row])
            for row in range(text.shape[0])
        ]

    @classmethod
    def _conditional_tree(cls, text, base, stats, columns, dependencies):
        """Build a bounded dependency-safe recursive value-partition prefix tree."""
        n, m = text.shape
        if n == 0 or m <= 1:
            return [base[:] for _ in range(n)]

        # Factorize each column once; all tree nodes reuse these integer codes.
        codes = []
        value_lengths = []
        for col in range(m):
            mapping = {}
            code_array = np.empty(n, dtype=np.int32)
            lengths = {}
            next_code = 0
            for row, value in enumerate(text[:, col]):
                if value not in mapping:
                    mapping[value] = next_code
                    lengths[next_code] = len(value)
                    next_code += 1
                code_array[row] = mapping[value]
            codes.append(code_array)
            value_lengths.append(lengths)

        predecessors = [set() for _ in range(m)]
        for left, right in cls._dependency_edges(columns, dependencies):
            predecessors[right].add(left)

        base_rank = {col: pos for pos, col in enumerate(base)}
        result = [None] * n
        node_count = [0]
        max_nodes = 128
        max_depth = min(m, 6)
        max_candidates = min(m, 24)

        def finish(rows, selected):
            """Append a deterministic dependency-safe tail to each leaf row."""
            chosen = set(selected)
            order = list(selected)
            remaining = [c for c in base if c not in chosen]

            while remaining:
                ready = [
                    c for c in remaining
                    if predecessors[c].issubset(chosen)
                ]
                if not ready:
                    ready = remaining
                col = min(ready, key=lambda c: base_rank[c])
                order.append(col)
                chosen.add(col)
                remaining.remove(col)

            for row in rows:
                result[row] = order[:]

        def visit(rows, selected, depth):
            """Choose a locally repetitive available field and recurse by value."""
            node_count[0] += 1
            if (
                not rows
                or depth >= max_depth
                or node_count[0] > max_nodes
                or len(selected) >= m
            ):
                finish(rows, selected)
                return

            chosen = set(selected)
            available = [
                c for c in base
                if c not in chosen and predecessors[c].issubset(chosen)
            ]
            if not available:
                finish(rows, selected)
                return

            available.sort(
                key=lambda c: (-stats[c][0], -stats[c][1], base_rank[c])
            )
            available = available[:max_candidates]

            best_col = None
            best_key = None
            for col in available:
                counts = {}
                for row in rows:
                    code = int(codes[col][row])
                    counts[code] = counts.get(code, 0) + 1

                gain = sum(
                    value_lengths[col][code] * count * (count - 1)
                    for code, count in counts.items()
                    if count > 1
                )
                key = (gain, stats[col][1], stats[col][2], -base_rank[col])
                if best_key is None or key > best_key:
                    best_key = key
                    best_col = col

            if best_col is None or best_key[0] <= 0:
                finish(rows, selected)
                return

            groups = {}
            for row in rows:
                code = int(codes[best_col][row])
                groups.setdefault(code, []).append(row)

            next_selected = selected + [best_col]
            if len(groups) <= 1:
                finish(rows, next_selected)
                return

            for group in groups.values():
                visit(group, next_selected, depth + 1)

        visit(list(range(n)), [], 0)

        for row in range(n):
            if result[row] is None:
                finish([row], [])
        return result

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort by serialized text and materialize only original source cells."""
        n, m = source.shape
        row_order = sorted(range(n), key=lambda row: (serialized[row], row))
        output = np.empty((n, m), dtype=object)
        public_orders = []

        for output_row, source_row in enumerate(row_order):
            order = orders[source_row]
            output[output_row, :] = [source[source_row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            output,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Compare one global frequency order with one bounded conditional tree."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        n, m = df.shape
        if n == 0 or m == 0:
            result = df.copy()
            orders = [[] for _ in range(n)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((n, m), dtype=object)
        for col in range(m):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        columns = list(df.columns)
        stats = self._statistics(text)

        # Merge constraints are represented as precedence chains, preserving
        # the existing API while allowing both a single chain and chain lists.
        dependencies = list(one_way_dep or [])
        if col_merge:
            if (
                isinstance(col_merge, (list, tuple))
                and col_merge
                and not isinstance(col_merge[0], (list, tuple))
            ):
                dependencies.append(col_merge)
            else:
                dependencies.extend(col_merge)

        preference = sorted(
            range(m),
            key=lambda col: (
                -stats[col][0],
                -stats[col][1],
                -stats[col][2],
                col,
            ),
        )
        preference = self._constrained_order(
            m, preference, columns, dependencies
        )

        global_orders = [preference[:] for _ in range(n)]
        tree_orders = self._conditional_tree(
            text,
            preference,
            stats,
            columns,
            dependencies,
        )

        best_score = -1
        best_orders = None
        best_serialized = None

        for orders in (global_orders, tree_orders):
            serialized = self._serialize(text, orders)
            score = self._trie_score(serialized)
            if score > best_score:
                best_score = score
                best_orders = orders
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )

        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

